/**
 * TradeLab Telegram Bot — Cloudflare Workers (stateless)
 *
 * Webhook-режим: Telegram шлёт обновления на URL.
 * Не читает файлы — данные берутся из.environ или KV.
 */

// In Cloudflare Workers, secrets are available as globalThis properties
// or via env parameter in module format
const BOT_TOKEN = (typeof globalThis !== 'undefined' && globalThis.TELEGRAM_BOT_TOKEN)
  || (typeof globalThis !== 'undefined' && globalThis.env && globalThis.env.TELEGRAM_BOT_TOKEN)
  || (typeof process !== 'undefined' && process.env && process.env.TELEGRAM_BOT_TOKEN)
  || '';

const CHAT_ID = (typeof globalThis !== 'undefined' && globalThis.TELEGRAM_CHAT_ID)
  || (typeof globalThis !== 'undefined' && globalThis.env && globalThis.env.TELEGRAM_CHAT_ID)
  || (typeof process !== 'undefined' && process.env && process.env.TELEGRAM_CHAT_ID)
  || '';

// ===== Telegram API =====

async function sendMessage(chatId, text) {
  const url = `https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`;
  const resp = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text: text
    })
  });
  const data = await resp.json();
  console.log('Send result:', data.ok, data.description || 'sent');
  return data;
}

// ===== Command Handlers =====

function handleStatus() {
  const now = new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' });
  return [
    'TradeLab Bot',
    now,
    '',
    'Bot is running on Cloudflare Workers.',
    'Type /help for commands.'
  ].join('\n');
}

function handleHelp() {
  return [
    'TradeLab Bot Commands',
    '',
    '/status - Bot status',
    '/help - This message',
    '',
    'This bot runs on Cloudflare Workers (free 24/7).'
  ].join('\n');
}

// ===== Webhook Handler =====

async function handleWebhook(request) {
  try {
    const update = await request.json();
    if (!update.message) return new Response('ok');

    const msg = update.message;
    const text = (msg.text || '').trim().toLowerCase();
    const chatId = String(msg.chat.id);

    console.log('Received:', text, 'from chat:', chatId);
    console.log('BOT_TOKEN set:', !!BOT_TOKEN, 'CHAT_ID:', CHAT_ID);

    if (chatId !== String(CHAT_ID)) {
      console.log('Chat ID mismatch:', chatId, '!=', CHAT_ID);
      return new Response('ok');
    }

    let response;
    switch (text) {
      case '/status': response = handleStatus(); break;
      case '/start':
      case '/help': response = handleHelp(); break;
      default: return new Response('ok');
    }

    await sendMessage(chatId, response);
    return new Response('ok');
  } catch (err) {
    return new Response('ok');
  }
}

// ===== Cloudflare Workers Entry Point =====

if (typeof globalThis !== 'undefined' && globalThis.addEventListener) {
  globalThis.addEventListener('fetch', event => {
    const url = new URL(event.request.url);

    if (url.pathname === '/webhook' && event.request.method === 'POST') {
      event.respondWith(handleWebhook(event.request));
    } else if (url.pathname === '/debug') {
      event.respondWith(new Response(JSON.stringify({
        hasToken: !!BOT_TOKEN,
        hasChatId: !!CHAT_ID,
        chatIdLength: CHAT_ID.length,
        tokenLength: BOT_TOKEN.length,
        globalThisKeys: Object.keys(globalThis).filter(k => k.includes('TELEGRAM') || k.includes('CHAT'))
      }, null, 2)));
    } else {
      event.respondWith(new Response('TradeLab Bot is running. POST to /webhook'));
    }
  });
}

if (typeof module !== 'undefined') {
  module.exports = { handleWebhook, sendMessage, handleStatus, handleHelp };
}
